// data-quran-learning.js — данные вынесены из index.html при разбивке на части (build 5.68).
// Загружается ДО основного логического скрипта через <script src="data-quran-learning.js"></script>.

    const LETTER_SOUND = {
      'ا':'أَلِف', 'ب':'بَاء', 'ت':'تَاء', 'ث':'ثَاء', 'ج':'جِيم',
      'ح':'حَاء', 'خ':'خَاء', 'د':'دَال', 'ذ':'ذَال', 'ر':'رَاء',
      'ز':'زَاي', 'س':'سِين', 'ش':'شِين', 'ص':'صَاد', 'ض':'ضَاد',
      'ط':'طَاء', 'ظ':'ظَاء', 'ع':'عَيْن', 'غ':'غَيْن', 'ف':'فَاء',
      'ق':'قَاف', 'ك':'كَاف', 'ل':'لَام', 'م':'مِيم', 'ن':'نُون',
      'ه':'هَاء', 'و':'وَاو', 'ي':'يَاء'
    };

    const ARABIC_LETTERS = [
      {ch:'ا', name:'Алиф', nameKk:'Әліп', tr:'ā / a', audio:'1_alif.mp3', forms:['ا','ا','ـا','ـا'], note:'Место образования — «пустота» рта и горла (аль-джауф): язык и губы полностью пассивны. Как самостоятельная буква алиф — не согласный, а знак долготы: продлевает звук «а» на 2 счёта (اَ = آ). Как носитель хамзы (أ/إ) в начале слова — это уже гортанный согласный (см. «Хамза»). Ошибка новичков — «зажимать» горло при чтении алифа, будто это خ или ح; горло должно быть расслаблено. Примеры: كِتَاب (китаб — книга), قَالَ (қāля — сказал). Сравните долготу: بَ (ба, кратко) и بَا (ба̄, с алифом, вдвое дольше).', noteKk:'Шығу орны — аузаралық/тамақтық қуыс (әл-джауф): тіл мен ерін мүлде қатыспайды. Дербес әріп ретінде әліп дауыссыз емес, ұзақтық белгісі: «а» дыбысын 2 харакатқа созады (اَ = آ). Сөз басында хамзаның тасушысы (أ/إ) болғанда — бұл көмейлік дауыссыз (қараңыз «Хамза»). Жаңадан үйренушінің қатесі — әліпті خ немесе ح сияқты тамақпен «қысу»; тамақ босаң болуы керек. Мысалдар: كِتَاب (китаб — кітап), قَالَ (қāля — айтты). Ұзақтықты салыстырыңыз: بَ (ба, қысқа) және بَا (ба̄, әліппен, екі есе ұзақ).'},
      {ch:'ب', name:'Ба', nameKk:'Ба', tr:'b', audio:'2_baa.mp3', forms:['ب','بـ','ـبـ','ـب'], note:'Место образования — обе губы, полностью смыкаются и резко размыкаются (шафатайн). Звонкая (джахр — связки работают), смычная (шидда — полная задержка воздуха), лёгкая/некатегоричная (истифаль). Входит в 5 букв калькаля (قطبجد) — на сукуне даёт лёгкий «отскок»: قَلْب (қальб — сердце) звучит с чуть заметным эхо на «б». Не смягчайте, как русское «бь». Примеры: بَاب (баб — дверь), رَبّ (рабб — Господь, с шаддой — губы держат смычку дольше).', noteKk:'Шығу орны — екі ерін, толық жабылып, кенет ашылады (шафатайн). Дауысты (жәһр), толық тұйықталатын (шидда), жеңіл (истифаль). Қалқаля 5 әрпінің бірі (قطبجد) — сукунда жеңіл «серпіліс» береді: قَلْب (қальб — жүрек) сөзінде «б»-да байқалатын жаңғырық бар. Орысша жұмсақ «бь» етіп айтпаңыз. Мысалдар: بَاب (баб — есік), رَبّ (рабб — Раб, шаддамен — еріндер тұйықталуды ұзағырақ ұстайды).'},
      {ch:'ت', name:'Та', nameKk:'Та', tr:'t', audio:'3_taa.mp3', forms:['ت','تـ','ـتـ','ـت'], note:'Место образования — кончик языка касается основания верхних резцов (края дёсен), чуть выше, чем для ث. Глухая (хамс — без голоса, только выдох), смычная (шидда), лёгкая (истифаль) — в отличие от «тяжёлой» ط. Не путайте с ط: ت — тонкий, передний звук, ط — глубокий, оттянутый назад. Минимальная пара: تِين (тин — инжир) и طِين (ṭин — глина) — звучат совсем по-разному. Пример: تَابَ (таба — покаялся).', noteKk:'Шығу орны — тіл ұшы жоғарғы азу тістердің түбіне (қалқа шетіне) тиеді, ث-ға қарағанда сәл жоғарырақ. Дауыссыз (хамс — дауыс жоқ, тек дем), тұйықталатын (шидда), жеңіл (истифаль) — «ауыр» ط-ға қарағанда. ط-мен шатастырмаңыз: ت — жіңішке, алдыңғы дыбыс, ط — терең, артқа тартылған. Минималды жұп: تِين (тин — інжір) және طِين (ṭин — балшық) — мүлде басқаша естіледі. Мысал: تَابَ (таба — тәубе етті).'},
      {ch:'ث', name:'Са (саʼ)', nameKk:'Са', tr:'θ (th)', audio:'4_thaa.mp3', forms:['ث','ثـ','ـثـ','ـث'], note:'Место образования — кончик языка МЕЖДУ передними верхними и нижними зубами (межзубный), воздух проходит со свистящим шумом — как английское th в think. Глухая (хамс), щелевая (ракава — воздух идёт непрерывно, не задерживается). Частая ошибка — заменять на «с» или «т»: ثَابِت (сабит) и سَابِق (сабиқ) — разные звуки и смыслы. Проверка: произнесите, слегка прикусив кончик языка — если звук не «свистит» между зубами, это неверно. Пример: ثَلَاثَة (саляса — три).', noteKk:'Шығу орны — тіл ұшы жоғарғы және төменгі алдыңғы тістердің АРАСЫНДА (тісаралық), ауа ысқырықты дыбыспен өтеді — ағылшынның think сөзіндегідей. Дауыссыз (хамс), үздіксіз ауа өтетін (ракава). Жиі кездесетін қате — «с» немесе «т»-ға ауыстыру: ثَابِت (сабит) мен سَابِق (сабиқ) — басқа дыбыс, басқа мағына. Тексеру: тіл ұшын жеңіл тістеп айтыңыз — тіс арасында ысқырық болмаса, қате. Мысал: ثَلَاثَة (саляса — үш).'},
      {ch:'ج', name:'Джим', nameKk:'Жим', tr:'j (дж)', audio:'5_jeem.mp3', forms:['ج','جـ','ـجـ','ـج'], note:'Место образования — средняя часть спинки языка прижимается к твёрдому нёбу (шакру-ль-фам), затем резко отпускается. Звонкая (джахр), смычная (шидда) — входит в 5 букв калькаля (قطبجد), даёт эхо на сукуне: يَخْرُجْ (яхрудж). Произносится ЕДИНЫМ звуком «дж», а не раздельно «д»+«ж». В некоторых региональных чтениях звучит как твёрдое «г», но в классическом таджвиде — «дж». Пример: جَنَّة (джанна — рай).', noteKk:'Шығу орны — тілдің ортаңғы бөлігі қатты таңдайға тиеді (шақру-ль-фам), сосын кенет ажырайды. Дауысты (жәһр), тұйықталатын (шидда) — қалқаля 5 әрпінің бірі (قطبجد), сукунда жаңғырық береді: يَخْرُجْ (яхрудж). БІРТҰТАС «дж» дыбысы ретінде айтылады, «д»+«ж» бөлек емес. Кейбір аймақтық оқылымдарда қатаң «г»-ге ұқсас естіледі, бірақ классикалық тәжуидте — «дж». Мысал: جَنَّة (жанна — жәннат).'},
      {ch:'ح', name:'Ха (ħа)', nameKk:'Ха', tr:'ħ', audio:'6_haa.mp3', forms:['ح','حـ','ـحـ','ـح'], note:'Место образования — середина горла (васат аль-халк), та же зона, что у ع, но без голоса. Глухая (хамс), щелевая (ракава). Это сильный тёплый выдох, будто вы дышите на замёрзшее стекло, — БЕЗ хрипа и без голоса. Не путайте с خ (тот образуется выше, ближе ко рту, и звучит хрипло) и с ه (та же зона, но звук намного слабее и легче). Минимальная пара: حَال (хāль — состояние) и خَال (х̮āль — дядя по матери). Пример: حَمْد (хамд — хвала).', noteKk:'Шығу орны — тамақтың ортасы (уасат әл-халк), ع-мен бір аймақ, бірақ дауыссыз. Дауыссыз (хамс), үздіксіз (ракава). Бұл — мұзданған әйнекке үрлегендей күшті жылы дем, ХЫРЫЛСЫЗ және дауыссыз. خ-мен шатастырмаңыз (ол жоғарырақ, аузға жақынырақ жасалады және хырылдап шығады) және ه-мен де (сол аймақ, бірақ дыбыс әлдеқайда әлсіз әрі жеңіл). Минималды жұп: حَال (хāль — жағдай) және خَال (х̮āль — нағашы). Мысал: حَمْد (хамд — мадақ).'},
      {ch:'خ', name:'Хаʼ (х̮а)', nameKk:'Хә', tr:'x', audio:'7_khaa.mp3', forms:['خ','خـ','ـخـ','ـخ'], note:'Место образования — верхняя часть горла, ближе ко рту (адна аль-халк), у мягкого нёба — как немецкое ch в Bach. Глухая (хамс), щелевая (ракава), «тяжёлая» (истиля — одна из 7 букв тафхим: خص ضغط قظ) — язык приподнят к нёбу, звук глубокий и объёмный. Отличие от ح: خ хрипит, ح — чистый выдох без хрипа. Пример: خَيْر (х̮айр — добро), сравните с حَيْر (путаница) — разные слова.', noteKk:'Шығу орны — тамақтың жоғарғы бөлігі, аузға жақынырақ (адна әл-халк), жұмсақ таңдай маңы — неміс тіліндегі Bach сөзіндегі ch сияқты. Дауыссыз (хамс), үздіксіз (ракава), «ауыр» (истиля — тафхим 7 әрпінің бірі: خص ضغط قظ) — тіл таңдайға көтеріледі, дыбыс терең әрі көлемді. ح-дан айырмашылығы: خ хырылдайды, ح — хырылсыз таза дем. Мысал: خَيْر (х̮айр — қайыр), حَيْر (шатасу) сөзімен салыстырыңыз — екеуі басқа сөз.'},
      {ch:'د', name:'Даль', nameKk:'Дәл', tr:'d', audio:'8_daal.mp3', forms:['د','د','ـد','ـد'], note:'Место образования — кончик языка у основания верхних резцов, там же, где ت, но со звонкостью. Звонкая (джахр), смычная (шидда), лёгкая (истифаль). Входит в 5 букв калькаля (قطبجد) — на сукуне звук слегка «отскакивает»: أَحَدْ (ахад). Не соединяется с буквой слева — после даль следующая буква пишется отдельно. Не путайте с «тяжёлой» ض. Пример: دِين (дин — религия), يَدٌ (ядун — рука).', noteKk:'Шығу орны — тіл ұшы жоғарғы азу тістердің түбінде, ت-мен бір жерде, бірақ дауыстылықпен. Дауысты (жәһр), тұйықталатын (шидда), жеңіл (истифаль). Қалқаля 5 әрпінің бірі (قطبجد) — сукунда дыбыс сәл «серпіледі»: أَحَدْ (ахад). Сол жағындағы әріппен қосылмайды — дальден кейінгі әріп бөлек жазылады. «Ауыр» ض-пен шатастырмаңыз. Мысал: دِين (дин — дін), يَدٌ (ядун — қол).'},
      {ch:'ذ', name:'Заль', nameKk:'Заль', tr:'ð (dh)', audio:'9_zaal.mp3', forms:['ذ','ذ','ـذ','ـذ'], note:'Место образования — межзубный, там же, где ث, но звонкая версия — как английское the. Звонкая (джахр), щелевая (ракава), лёгкая (истифаль). Не соединяется слева. Частая ошибка — заменять на «з» (без языка между зубами): проверяйте, чтобы кончик языка был виден между зубами. Минимальная пара: ذَٰلِكَ (залика — тот/это) — не «залика» с обычной «з». Пример: ذَهَب (заhаб — золото/ушёл).', noteKk:'Шығу орны — тісаралық, ث-мен бір жер, бірақ дауысты нұсқасы — ағылшынның the сөзіндегідей. Дауысты (жәһр), үздіксіз (ракава), жеңіл (истифаль). Сол жағынан қосылмайды. Жиі кездесетін қате — «з»-ге ауыстыру (тіл тіс арасында болмайды): тіл ұшы тіс арасында көрініп тұрғанын тексеріңіз. Минималды жұп: ذَٰلِكَ (залика — сол/бұл) — қарапайым «з»-мен емес. Мысал: ذَهَب (заһаб — алтын/кетті).'},
      {ch:'ر', name:'Ра', nameKk:'Ра', tr:'r', audio:'10_raa.mp3', forms:['ر','ر','ـر','ـر'], note:'Место образования — кончик языка слегка загибается к дёснам за верхними резцами, с лёгкой одиночной вибрацией (текрар — не раскатывайте, как русское «р», хватает 1–2 касаний). Звонкая (джахр), «между смычной и щелевой» (тавассут). Меняет «вес»: тяжёлая (тафхим) с фатхой/даммой или на сукуне после них — رَبّ (рабб); лёгкая (тарқик) с касрой — رِزْق (ризқ). Не соединяется слева. Пример: قُرْآن (Қур’ан).', noteKk:'Шығу орны — тіл ұшы жоғарғы азу тістер артындағы қалқаға сәл бүгіледі, жеңіл жалғыз дірілмен (текрар — орысша «р» сияқты сылдырлатпаңыз, 1–2 тиюі жеткілікті). Дауысты (жәһр), «тұйықталу мен үздіксіздің арасы» (тавассут). «Салмағы» өзгереді: фатха/дамманың алдында немесе одан кейінгі сукунда ауыр (тафхим) — رَبّ (рабб); касрамен жеңіл (тарқиқ) — رِزْق (ризқ). Сол жағынан қосылмайды. Мысал: قُرْآن (Құран).'},
      {ch:'ز', name:'Зай', nameKk:'Зай', tr:'z', audio:'11_zaa.mp3', forms:['ز','ز','ـز','ـز'], note:'Место образования — кончик языка у нижних зубов, воздух проходит узкой щелью со свистом (сафир — свистящая буква, как س и ص). Звонкая (джахр), щелевая (ракава), лёгкая (истифаль). Не соединяется слева. Отличие от ذ: ز — зубной свистящий звук, язык НЕ между зубами. Пример: زَيْتُون (зайтун — олива), زَكَاة (закят — обязательная милостыня).', noteKk:'Шығу орны — тіл ұшы төменгі тістер маңында, ауа тар саңылаумен ысқырықпен өтеді (сафир — ысқырықты әріп, س және ص сияқты). Дауысты (жәһр), үздіксіз (ракава), жеңіл (истифаль). Сол жағынан қосылмайды. ذ-дан айырмашылығы: ز — тістік ысқырықты дыбыс, тіл тіс арасында ЕМЕС. Мысал: زَيْتُون (зайтун — зәйтүн), زَكَاة (зәкет — міндетті садақа).'},
      {ch:'س', name:'Син', nameKk:'Син', tr:'s', audio:'12_seen.mp3', forms:['س','سـ','ـسـ','ـس'], note:'Место образования — та же зона, что у ز и ص (кончик языка у нижних зубов, узкая щель), но глухая. Глухая (хамс), щелевая (ракава), свистящая (сафир), лёгкая (истифаль) — в отличие от «тяжёлой» ص. Минимальная пара: سِر (сир — иди/тайна) и صِر (ṣир) — разный «вес» звука: с ص язык оттянут назад и слегка приподнят, звук объёмнее. Пример: سَلَام (салям — мир), سُورَة (сура).', noteKk:'Шығу орны — ز және ص-мен бір аймақ (тіл ұшы төменгі тістер маңында, тар саңылау), бірақ дауыссыз. Дауыссыз (хамс), үздіксіз (ракава), ысқырықты (сафир), жеңіл (истифаль) — «ауыр» ص-ға қарағанда. Минималды жұп: سِر (сир — жүр/сыр) және صِر (ṣир) — дыбыс «салмағы» басқа: ص-да тіл артқа тартылып, сәл көтеріледі, дыбыс көлемдірек. Мысал: سَلَام (салям — амандық), سُورَة (сүре).'},
      {ch:'ش', name:'Шин', nameKk:'Шин', tr:'š (ш)', audio:'13_sheen.mp3', forms:['ش','شـ','ـشـ','ـش'], note:'Место образования — средняя часть языка ближе к нёбу, шире, чем у س: воздух рассеивается по всей ширине языка (тафашши — «распространение», уникальное качество этой буквы). Глухая (хамс), щелевая (ракава), лёгкая (истифаль). Не путать с ج (тот смычный и звонкий). Пример: شَمْس (шамс — солнце), شُكْر (шукр — благодарность).', noteKk:'Шығу орны — тілдің ортаңғы бөлігі таңдайға жақынырақ, س-ге қарағанда кеңірек: ауа тілдің бүкіл ені бойымен тарайды (тафашши — «таралу», осы әріпке ғана тән қасиет). Дауыссыз (хамс), үздіксіз (ракава), жеңіл (истифаль). ج-мен шатастырмаңыз (ол тұйықталатын әрі дауысты). Мысал: شَمْس (шамс — күн), شُكْر (шүкір — алғыс).'},
      {ch:'ص', name:'Сад', nameKk:'Сад', tr:'ṣ', audio:'14_saad.mp3', forms:['ص','صـ','ـصـ','ـص'], note:'Место образования — та же зона, что у س, но «тяжёлая»: задняя часть языка приподнимается к нёбу (истиля — одна из 7 букв тафхим: خص ضغط قظ) и прижимается к нёбу (итбак). Глухая (хамс), щелевая (ракава), свистящая (сафир). Звук объёмный, «толстый», рот будто наполняется звуком. Минимальная пара: صَبْر (ṣабр — терпение) и سَبْر (сабр — исследование) — разные слова. Пример: صَلَاة (ṣаля — молитва).', noteKk:'Шығу орны — س-мен бір аймақ, бірақ «ауыр»: тілдің артқы бөлігі таңдайға көтеріледі (истиля — тафхим 7 әрпінің бірі: خص ضغط قظ) және таңдайға жабысады (итбак). Дауыссыз (хамс), үздіксіз (ракава), ысқырықты (сафир). Дыбыс көлемді, «қалың», ауыз дыбысқа толғандай болады. Минималды жұп: صَبْر (ṣабр — сабыр) және سَبْر (сабр — зерттеу) — басқа сөздер. Мысал: صَلَاة (ṣаля — намаз).'},
      {ch:'ض', name:'Дад', nameKk:'Дад', tr:'ḍ', audio:'15_daad.mp3', forms:['ض','ضـ','ـضـ','ـض'], note:'Самая сложная буква арабского языка — недаром арабский называют «языком дад» (люгату-д-дад). Место образования — один или оба края языка (обычно левый) прижимаются к верхним коренным зубам, воздух идёт вдоль всей боковой поверхности языка до кончика (иститала — «протяжённость», уникальное качество только этой буквы). Звонкая (джахр), тяжёлая (истиля, итбак). Не путайте с ظ (межзубная) и д (простая зубная). Учите только со слуха и, если есть возможность, с учителем/устазом. Пример: ضَلَّ (далля — заблудился), رَمَضَان (Рамадан).', noteKk:'Араб тіліндегі ең күрделі әріп — тегін емес араб тілін «дад тілі» (люғату-д-дад) деп атайды. Шығу орны — тілдің бір немесе екі шеті (әдетте сол жағы) жоғарғы азу тістерге жабысады, ауа тілдің бүкіл бүйір бетімен ұшына дейін жүреді (иститала — «созылыңқылық», тек осы әріпке тән қасиет). Дауысты (жәһр), ауыр (истиля, итбак). ظ-мен (тісаралық) және қарапайым д-мен шатастырмаңыз. Тек құлақпен, мүмкіндігінше ұстаздан үйреніңіз. Мысал: ضَلَّ (далля — адасты), رَمَضَان (Рамазан).'},
      {ch:'ط', name:'Та (ṭа)', nameKk:'Та (ṭа)', tr:'ṭ', audio:'16_taah.mp3', forms:['ط','طـ','ـطـ','ـط'], note:'Место образования — та же зона, что у ت, но «тяжёлая»: задняя часть языка поднимается к нёбу (истиля, итбак). Важно: в отличие от ت (глухая), буква ط — ЗВОНКАЯ (джахр), смычная (шидда), входит в 5 букв калькаля (قطبجد). Минимальная пара: تِين (тин — инжир) и طِين (ṭин — глина). Пример: طَالِب (ṭāлиб — студент), قَطْعًا (қаṭ‘ан — определённо, с калькаля на сукуне).', noteKk:'Шығу орны — ت-мен бір аймақ, бірақ «ауыр»: тілдің артқы бөлігі таңдайға көтеріледі (истиля, итбак). Маңызды: ت-дан (дауыссыз) айырмашылығы — ط ӘРІПІ ДАУЫСТЫ (жәһр), тұйықталатын (шидда), қалқаля 5 әрпінің бірі (قطبجد). Минималды жұп: تِين (тин — інжір) және طِين (ṭин — балшық). Мысал: طَالِب (ṭāлиб — студент), قَطْعًا (қаṭ‘ан — сөзсіз, сукунда қалқалямен).'},
      {ch:'ظ', name:'За (ẓа)', nameKk:'За (ẓа)', tr:'ẓ', audio:'17_zhaa.mp3', forms:['ظ','ظـ','ـظـ','ـظ'], note:'Место образования — межзубная, как ذ, но «тяжёлая»: задняя часть языка приподнята (истиля, итбак). Звонкая (джахр), щелевая (ракава). Самая редкая буква арабского алфавита. Не путайте с ض (та боковая, не межзубная) и с ز (та без языка между зубами). Проверка: язык должен быть виден между зубами, звук — глубокий и объёмный. Пример: ظُلْم (ẓульм — несправедливость), عَظِيم (аẓым — великий).', noteKk:'Шығу орны — тісаралық, ذ сияқты, бірақ «ауыр»: тілдің артқы бөлігі көтеріледі (истиля, итбак). Дауысты (жәһр), үздіксіз (ракава). Араб әліпбиіндегі ең сирек кездесетін әріп. ض-пен (ол бүйірлік, тісаралық емес) және ز-мен (тіл тіс арасында емес) шатастырмаңыз. Тексеру: тіл тіс арасында көрінуі керек, дыбыс — терең әрі көлемді. Мысал: ظُلْم (ẓульм — әділетсіздік), عَظِيم (аẓым — ұлы).'},
      {ch:'ع', name:'Айн', nameKk:'Айн', tr:'ʿ', audio:'18_ain.mp3', forms:['ع','عـ','ـعـ','ـع'], note:'Место образования — середина горла (васат аль-халк), та же зона, что у ح, но со смыканием и голосом. Звонкая (джахр), «между смычной и щелевой» (тавассут). В русском и казахском языках точного аналога нет — учите только на слух. Не путайте с хамзой ء (та образуется глубже, в самом начале горла, без сжатия середины) и с غ (та мягче, без напряжения горла). Тренировка: عَ عِ عُ — чувствуйте лёгкое сжатие в середине горла. Пример: عِلْم (ильм — знание), عَرَبِيّ (арабий — арабский).', noteKk:'Шығу орны — тамақтың ортасы (уасат әл-халк), ح-мен бір аймақ, бірақ тұйықталумен және дауыспен. Дауысты (жәһр), «тұйықталу мен үздіксіздің арасы» (тавассут). Орыс және қазақ тілдерінде дәл сәйкесі жоқ — тек құлақпен үйреніңіз. Хамзамен ء шатастырмаңыз (ол тереңірек, тамақтың ең басында, ортаны қыспай жасалады) және غ-мен де (ол жұмсағырақ, тамақ керілмейді). Жаттығу: عَ عِ عُ — тамақтың ортасындағы жеңіл қысымды сезіңіз. Мысал: عِلْم (ильм — білім), عَرَبِيّ (арабий — арабша).'},
      {ch:'غ', name:'Гайн', nameKk:'Ғайн', tr:'ġ', audio:'19_ghain.mp3', forms:['غ','غـ','ـغـ','ـغ'], note:'Место образования — верхняя часть горла (адна аль-халк), та же зона, что у خ, но со звонким голосом — похоже на украинское «г» или картавое французское r. Звонкая (джахр), щелевая (ракава), тяжёлая (истиля — одна из 7 букв тафхим: خص ضغط قظ). Не путайте с ع (тот образуется глубже, в середине горла, со смыканием). Пример: غَفُور (гафур — прощающий), مَغْرِب (магриб — закат/запад).', noteKk:'Шығу орны — тамақтың жоғарғы бөлігі (адна әл-халк), خ-мен бір аймақ, бірақ дауысты дыбыспен — украин тіліндегі «г»-ге немесе француз тіліндегі R-ге ұқсас. Дауысты (жәһр), үздіксіз (ракава), ауыр (истиля — тафхим 7 әрпінің бірі: خص ضغط قظ). ع-мен шатастырмаңыз (ол тереңірек, тамақтың ортасында, тұйықталумен жасалады). Мысал: غَفُور (ғафур — кешірімді), مَغْرِب (мағриб — күн батыс).'},
      {ch:'ف', name:'Фа', nameKk:'Фа', tr:'f', audio:'20_faa.mp3', forms:['ف','فـ','ـفـ','ـف'], note:'Место образования — внутренний край верхних резцов касается внутренней стороны нижней губы (в отличие от русской «ф», где губа касается зубов снаружи — здесь чуть иначе, но звучание близкое). Глухая (хамс), щелевая (ракава), лёгкая (истифаль). Пример: فَتْح (фатх — открытие/победа), فِي (фи — в).', noteKk:'Шығу орны — жоғарғы азу тістердің ішкі жиегі төменгі еріннің ішкі бетіне тиеді (орысша «ф»-тен сәл өзгеше, бірақ дыбысы жақын). Дауыссыз (хамс), үздіксіз (ракава), жеңіл (истифаль). Мысал: فَتْح (фатх — жеңіс/ашылу), فِي (фи — -де/-да).'},
      {ch:'ق', name:'Қаф', nameKk:'Қаф', tr:'q', audio:'21_qaaf.mp3', forms:['ق','قـ','ـقـ','ـق'], note:'Место образования — САМЫЙ КОРЕНЬ языка (акса аль-лисан) поднимается к мягкому нёбу/увуле — глубже, чем ك. Звонкая (джахр), смычная (шидда), тяжёлая (истиля — одна из 7 букв тафхим: خص ضغط قظ), входит в 5 букв калькаля (قطبجد). Это одна из самых частых ошибок русско- и казахоязычных чтецов: и ق, и ك слышатся как обычная «к» — их нужно чётко различать. Минимальная пара: قَلْب (қальб — сердце, глубокая, звонкая) и كَلْب (кяльб — собака, лёгкая, глухая). Пример: قُرْآن (Қур’ан).', noteKk:'Шығу орны — тілдің ЕҢ ТҮБІ (ақса әл-лисан) жұмсақ таңдайға/кішкене тілге көтеріледі — ك-ден тереңірек. Дауысты (жәһр), тұйықталатын (шидда), ауыр (истиля — тафхим 7 әрпінің бірі: خص ضغط قظ), қалқаля 5 әрпінің бірі (قطبجد). Бұл — орыс және қазақ тілді оқырмандардың жиі жіберетін қатесі: ق мен ك екеуі де қарапайым «к» болып естіледі — оларды нақты ажырату керек. Минималды жұп: قَلْب (қальб — жүрек, терең, дауысты) және كَلْب (кяльб — ит, жеңіл, дауыссыз). Мысал: قُرْآن (Құран).'},
      {ch:'ك', name:'Кяф', nameKk:'Кәф', tr:'k', audio:'22_kaaf.mp3', forms:['ك','كـ','ـكـ','ـك'], note:'Место образования — задняя часть языка касается мягкого нёба, чуть ближе ко рту, чем у ق. Глухая (хамс — в отличие от звонкой ق!), смычная (шидда), лёгкая (истифаль — в отличие от тяжёлой ق). Обычная «к», как в русском или казахском. Отличайте от ق по глубине и звонкости — см. пример у буквы «Қаф». Пример: كِتَاب (китаб — книга), مَلِك (малик — царь).', noteKk:'Шығу орны — тілдің артқы бөлігі жұмсақ таңдайға тиеді, ق-ге қарағанда аузға жақынырақ. Дауыссыз (хамс — дауысты ق-ден айырмашылығы!), тұйықталатын (шидда), жеңіл (истифаль — ауыр ق-ден айырмашылығы). Орыс не қазақ тіліндегі әдеттегі «к». ق-ден тереңдігі мен дауыстылығы бойынша ажыратыңыз — «Қаф» әрпіндегі мысалды қараңыз. Мысал: كِتَاب (китаб — кітап), مَلِك (мәлик — патша).'},
      {ch:'ل', name:'Лям', nameKk:'Ләм', tr:'l', audio:'23_laam.mp3', forms:['ل','لـ','ـلـ','ـل'], note:'Место образования — край языка (один или оба) прижимается к дёснам за верхними резцами. Звонкая (джахр), «между смычной и щелевой» (тавассут), обычно лёгкая (тарқик). Особый случай — «лям величия» в имени الله (Аллах): если перед ней стоит фатха или дамма, лям читается тяжело (тафхим) — قَالَ اللهُ; если стоит касра — легко: بِسْمِ اللهِ. Пример: لَيْل (лейль — ночь), قَلَم (қалям — перо/ручка).', noteKk:'Шығу орны — тілдің шеті (бір немесе екеуі) жоғарғы азу тістер артындағы қалқаға жабысады. Дауысты (жәһр), «тұйықталу мен үздіксіздің арасы» (тавассут), әдетте жеңіл (тарқиқ). Ерекше жағдай — الله (Аллаһ) есіміндегі «ұлықтық ләмі»: алдында фатха немесе дамма тұрса, ләм ауыр оқылады (тафхим) — قَالَ اللهُ; касра тұрса — жеңіл: بِسْمِ اللهِ. Мысал: لَيْل (лейль — түн), قَلَم (қалям — қалам).'},
      {ch:'م', name:'Мим', nameKk:'Мим', tr:'m', audio:'24_meem.mp3', forms:['م','مـ','ـمـ','ـم'], note:'Место образования — обе губы смыкаются, как у ب, но голос идёт через нос (гунна — носовой призвук около 2 счётов). Звонкая (джахр), «между смычной и щелевой» (тавассут), лёгкая (истифаль). Гунна особенно заметна при идгаме и ихфа с мим-сукун перед другой мим или ба (اخفاء شفوي). Пример: مَاء (ма’ — вода), رَحْمَة (рахма — милость).', noteKk:'Шығу орны — екі ерін ب сияқты жабылады, бірақ дауыс мұрын арқылы шығады (гунна — шамамен 2 есептік мұрын дыбысы). Дауысты (жәһр), «тұйықталу мен үздіксіздің арасы» (тавассут), жеңіл (истифаль). Гунна әсіресе мим-сукун басқа мимнің немесе баның алдында келгенде идгам мен ихфада (ихфа шафауи) айқын байқалады. Мысал: مَاء (ма’ — су), رَحْمَة (рахма — мейірім).'},
      {ch:'ن', name:'Нун', nameKk:'Нун', tr:'n', audio:'25_noon.mp3', forms:['ن','نـ','ـنـ','ـن'], note:'Место образования — кончик языка у дёсен, близко к ل, но проход открыт в нос — голос частично идёт через нос (гунна, ~2 счёта). Звонкая (джахр), «между смычной и щелевой» (тавассут), лёгкая (истифаль). Именно нун-сукун и танвин — источник целой группы правил таджвида: изхар, идгам, иклаб, ихфа (см. раздел «Правила»). Пример: نُور (нур — свет), إِنَّ (инна — поистине, с шаддой — гунна дольше).', noteKk:'Шығу орны — тіл ұшы қалқада, ل-ге жақын, бірақ жол мұрынға ашық — дауыс жартылай мұрын арқылы шығады (гунна, ~2 есеп). Дауысты (жәһр), «тұйықталу мен үздіксіздің арасы» (тавассут), жеңіл (истифаль). Дәл нун-сукун мен тануин — тәжуидтің тұтас бір тобының көзі: изхар, идгам, иклаб, ихфа (қараңыз «Ережелер» бөлімі). Мысал: نُور (нұр — жарық), إِنَّ (инна — шын мәнінде, шаддамен — гунна ұзағырақ).'},
      {ch:'ه', name:'Һа', nameKk:'Һа', tr:'h', audio:'26_haah.mp3', forms:['ه','هـ','ـهـ','ـه'], note:'Место образования — самая глубина горла (акса аль-халк), та же зона, что у хамзы, но без смычки — просто лёгкий выдох. Глухая (хамс), щелевая (ракава), самая «слабая» и мягкая из горловых букв — намного легче, чем ح. Не напрягайте горло. Пример: هُدَى (худа — руководство/наставление), اللَّه (Аллаh — в конце слова буква едва слышна на выдохе).', noteKk:'Шығу орны — тамақтың ең түбі (ақса әл-халк), хамзамен бір аймақ, бірақ тұйықталусыз — жай ғана жеңіл дем. Дауыссыз (хамс), үздіксіз (ракава), көмейлік әріптердің ішіндегі ең «әлсізі» әрі жұмсағы — ح-ден әлдеқайда жеңіл. Тамақты керіп жібермеңіз. Мысал: هُدَى (худа — тура жол), اللَّه (Аллаһ — сөз соңында әріп демде әрең естіледі).'},
      {ch:'و', name:'Уау', nameKk:'Уау', tr:'ū / u', audio:'27_waw.mp3', forms:['و','و','ـو','ـو'], note:'Как долгая гласная (мадд) — образуется в «пустоте» рта (аль-джауф) с округлёнными в трубочку губами, продлевая «у» на 2 счёта. Как согласная — губы тоже округляются, но без зубов на губе (это НЕ русская «в»!). Звонкая (джахр), «между смычной и щелевой» (тавассут). Особое качество ляйин («мягкость») — когда стоит с сукуном после фатхи: قَوْل (қаўль — слово) — звучит мягко, почти как дифтонг «ау». Пример: وَلَد (валяд — мальчик), نُور (нур — свет, с долгим «у»).', noteKk:'Ұзын дауысты (мадд) ретінде — аузаралық қуыста (әл-джауф) еріндер түтікше сияқты дөңгеленіп, «у»-ды 2 харакатқа созады. Дауыссыз ретінде — еріндер де дөңгеленеді, бірақ тіс еринге тимейді (бұл орысша «в» ЕМЕС!). Дауысты (жәһр), «тұйықталу мен үздіксіздің арасы» (тавассут). Ерекше «ляйин» («жұмсақтық») қасиеті — фатхадан кейін сукунмен келгенде: قَوْل (қаўль — сөз) — жұмсақ, «ау» дифтонгіне жақын естіледі. Мысал: وَلَد (уәляд — бала), نُور (нұр — жарық, ұзын «у»-мен).'},
      {ch:'ي', name:'Йа', nameKk:'Йа', tr:'ī / y', audio:'30_yaa.mp3', forms:['ي','يـ','ـيـ','ـي'], note:'Как долгая гласная (мадд) — образуется в «пустоте» рта (аль-джауф), продлевая «и» на 2 счёта. Как согласная — средняя часть языка поднимается к твёрдому нёбу, как «й». Звонкая (джахр), «между смычной и щелевой» (тавассут). Особое качество ляйин («мягкость») — на сукуне после фатхи: بَيْت (байт — дом) — мягкий дифтонг «ай». Пример: يَد (яд — рука), فِي (фи — в, с долгим «и»).', noteKk:'Ұзын дауысты (мадд) ретінде — аузаралық қуыста (әл-джауф) «и»-ды 2 харакатқа созады. Дауыссыз ретінде — тілдің ортаңғы бөлігі қатты таңдайға көтеріледі, «й» сияқты. Дауысты (жәһр), «тұйықталу мен үздіксіздің арасы» (тавассут). Ерекше «ляйин» («жұмсақтық») қасиеті — фатхадан кейін сукунда: بَيْت (байт — үй) — жұмсақ «ай» дифтонгі. Мысал: يَد (яд — қол), فِي (фи — -де/-да, ұзын «и»-мен).'}
    ];

    const ACADEMY_PATH = [
      {
        id: 'm0', level: 0, title: 'Старт', titleKk: 'Бастау', icon: '🚀',
        goal: 'Понять, зачем арабский, и как устроено письмо',
        goalKk: 'Неге араб тілі керек екенін және жазудың қалай құрылғанын түсіну',
        lessons: [
          { id:'m0-1', title:'Зачем арабский для Корана', titleKk:'Құран үшін неге араб тілі керек', body:
`Коран ниспослан на ясном арабском языке (12:2, 43:3). Перевод передаёт смысл, но не заменяет звучание, ритм и точность оригинала.

Цель этого пути — не «выучить арабский как язык» за неделю, а научиться уверенно читать мусхаф: буквы → огласовки → слоги → слова → аяты → таджвид.

Рекомендация: 15–25 минут в день. Лучше каждый день понемногу, чем раз в неделю долго.` ,
            bodyKk:
`Құран анық араб тілінде түсірілген (12:2, 43:3). Аударма мағынаны жеткізеді, бірақ түпнұсқаның дыбысталуын, ырғағын және дәлдігін алмастырмайды.

Бұл жолдың мақсаты — бір аптада «араб тілін үйрену» емес, мұсхафты сенімді оқуды үйрену: әріптер → харакаттар → буындар → сөздер → аяттар → тәжуид.

Кеңес: күніне 15–25 минут. Аптасына бір рет ұзақ оқығаннан гөрі, күн сайын аздап оқыған дұрыс.` },
          { id:'m0-2', title:'Справа налево и формы букв', titleKk:'Оңнан солға және әріп түрлері', body:
`Арабский пишется и читается справа налево.

У большинства букв до 4 форм:
• изолированная (одна)
• начальная (в начале слова)
• срединная (в середине)
• конечная (в конце)

6 букв не соединяются со следующей (той, что слева): ا د ذ ر ز و

Практика: откройте вкладку «Буквы» и посмотрите формы каждой буквы.` ,
            bodyKk:
`Араб тілі оңнан солға қарай жазылады және оқылады.

Әріптердің көбінің 4-ке дейін түрі бар:
• оқшау (жеке)
• бастапқы (сөздің басында)
• ортаңғы (ортасында)
• соңғы (аяғында)

6 әріп келесі әріппен (сол жағындағымен) қосылмайды: ا د ذ ر ز و

Жаттығу: «Әріптер» бетін ашып, әр әріптің түрлерін қараңыз.` }
        ]
      },
      {
        id: 'm1', level: 1, title: 'Алфавит', titleKk: 'Әліпби', icon: 'ا ب ت',
        goal: 'Узнать 28 букв: вид, имя, звук, формы',
        goalKk: '28 әріпті тану: түрі, аты, дыбысы, жазылу үлгілері',
        lessons: [
          { id:'m1-1', title:'Группа 1: ا ب ت ث ج ح خ', titleKk:'1-топ: ا ب ت ث ج ح خ', body:
`ا Алиф — долгий «а» / носитель хамзы. Не соединяется слева.
ب Ба — «б»
ت Та — «т»
ث Са — межзубный th (think)
ج Джим — «дж»
ح Ха — глубокий глухой «ħ» из горла
خ Ха — «х» как в «хрип»

Откройте «Буквы», нажмите каждую, послушайте и повторите вслух 5 раз.` ,
            bodyKk:
`ا Әліп — ұзын «а» / хамзаның тасымалдаушысы. Сол жағынан қосылмайды.
ب Ба — «б»
ت Та — «т»
ث Са — тісаралық th (think)
ج Джим — «дж»
ح Ха — көмейден шығатын терең қатаң «ħ»
خ Ха — «хрип» дегендегідей «х»

«Әріптер» бетін ашып, әрқайсысын басып, тыңдап, дауыстап 5 рет қайталаңыз.` },
          { id:'m1-2', title:'Группа 2: د ذ ر ز س ش', titleKk:'2-топ: د ذ ر ز س ش', body:
`د Даль — «д», не соединяется слева
ذ Заль — межзубный dh (the)
ر Ра — раскатистая «р»
ز Зай — «з»
س Син — «с»
ش Шин — «ш»

Сравните ت/ث и د/ذ — разница в месте образования (кончик языка между зубами).` ,
            bodyKk:
`د Дәл — «д», сол жағынан қосылмайды
ذ Заль — тісаралық dh (the)
ر Ра — сыңғырлақ «р»
ز Зай — «з»
س Син — «с»
ش Шин — «ш»

ت/ث және د/ذ салыстырыңыз — айырмашылық жасалу орнында (тіл ұшы тістер арасында).` },
          { id:'m1-3', title:'Группа 3: ص ض ط ظ ع غ', titleKk:'3-топ: ص ض ط ظ ع غ', body:
`Эмфатические (язык оттянут назад, «твёрдые»):
ص Сад — твёрдое «ṣ»
ض Дад — уникальный эмфатический «ḍ»
ط Та — эмфатическое «ṭ»
ظ За — эмфатический межзубный

Горловые:
ع Айн — гортанный звук (нет в русском)
غ Гайн — как украинское «г» / фр. r` ,
            bodyKk:
`Эмфатикалық (тіл артқа тартылған, «қатты»):
ص Сад — қатты «ṣ»
ض Дад — бірегей эмфатикалық «ḍ»
ط Та — эмфатикалық «ṭ»
ظ За — эмфатикалық тісаралық

Көмейлік:
ع Айын — көмейден шығатын дыбыс (қазақ тілінде жоқ)
غ Ғайын — украин тіліндегі «г» / фр. r тәрізді` },
          { id:'m1-4', title:'Группа 4: ف ق ك ل م ن ه و ي', titleKk:'4-топ: ف ق ك ل م ن ه و ي', body:
`ф Фа — «ф»
ق Қаф — глубокая «қ» из горла (не «к»)
ك Кяф — обычная «к»
ل Лям — «л»
م Мим — «м»
ن Нун — «н»
ه Һа — лёгкий выдох «h»
و Уау — «у/ū», НЕ русская «в». Не соединяется слева
ي Йа — «й/ī»

Когда все 28 узнаёте в любой форме — переходите к огласовкам.` ,
            bodyKk:
`ف Фа — «ф»
ق Қаф — көмейден шығатын терең «қ» («к» емес)
ك Кәф — қарапайым «к»
ل Лям — «л»
م Мим — «м»
ن Нун — «н»
ه Һа — жеңіл тыныс «h»
و Уау — «у/ū», орыс тіліндегі «в» ЕМЕС. Сол жағынан қосылмайды
ي Йа — «й/ī»

Барлық 28 әріпті кез келген түрінде танитын болғанда — харакаттарға өтіңіз.` }
        ]
      },
      {
        id: 'm2', level: 2, title: 'Огласовки', titleKk: 'Харакаттар', icon: 'َ ِ ُ',
        goal: 'Читать любую букву с фатхой, касрой, даммой, сукуном, шаддой',
        goalKk: 'Кез келген әріпті фатха, касра, дамма, сукун, шаддамен оқу',
        lessons: [
          { id:'m2-1', title:'Три краткие гласные', titleKk:'Үш қысқа дауысты', body:
`فَتْحَة َ = а (над буквой)
كَسْرَة ِ = и (под буквой)
ضَمَّة ُ = у (над буквой)

بَ = ба · بِ = би · بُ = бу

Без огласовок взрослый араб читает по смыслу; в Коране (особенно учебном) огласовки стоят почти всегда.

Практика: вкладка «Огласовки» и «Слоги».` ,
            bodyKk:
`فَتْحَة َ = а (әріптің үстінде)
كَسْرَة ِ = и (әріптің астында)
ضَمَّة ُ = у (әріптің үстінде)

بَ = ба · بِ = би · بُ = бу

Харакатсыз ересек араб мағынасы бойынша оқиды; Құранда (әсіресе оқу нұсқасында) харакаттар дерлік әрқашан тұрады.

Жаттығу: «Харакаттар» және «Буындар» беттері.` },
          { id:'m2-2', title:'Сукун и шадда', titleKk:'Сукун және шадда', body:
`سُكُون ْ — нет гласной. مِنْ = мин
شَدَّة ّ — удвоение. رَبِّ = раб-би

При шадде: сначала «закрытый» согласный, потом тот же с гласной.

Танвин ً ٍ ٌ = an / in / un на конце слова (неопределённость).` ,
            bodyKk:
`سُكُون ْ — дауысты жоқ. مِنْ = мин
شَدَّة ّ — қосарлану. رَبِّ = раб-би

Шаддада: алдымен «жабық» дауыссыз, сосын сол дауыссыз харакатпен.

Тануин ً ٍ ٌ = сөз соңында an / in / un (белгісіздік).` },
          { id:'m2-3', title:'Долгие гласные', titleKk:'Ұзын дауыстылар', body:
`Долгий ā: буква + алиф (or ٰ) → بَا = баа
Долгий ī: касра + йа → بِي = бии
Долгий ū: дамма + уау → بُو = буу

В таджвиде долгие тянутся ~2 счёта (естественный мадд).` ,
            bodyKk:
`Ұзын ā: әріп + әліп (немесе ٰ) → بَا = баа
Ұзын ī: касра + йа → بِي = бии
Ұзын ū: дамма + уау → بُو = буу

Тәжуидте ұзын дауыстылар ~2 есеп созылады (табиғи мадд).` }
        ]
      },
      {
        id: 'm3', level: 3, title: 'Слоги и слова', titleKk: 'Буындар мен сөздер', icon: '📖',
        goal: 'Складывать слоги в слова и читать простые слова с огласовками',
        goalKk: 'Буындарды сөзге құрап, харакатты қарапайым сөздерді оқу',
        lessons: [
          { id:'m3-1', title:'Слоги CV и CVC', titleKk:'CV және CVC буындары', body:
`CV: согласный + гласная → بَ تِ مُ
CVC: + сукун → بَتْ مِنْ كُتْ

Читайте справа налево по слогам, не «угадывая» слово целиком, пока не станет привычкой.

Вкладка «Слоги» — тренажёр.` ,
            bodyKk:
`CV: дауыссыз + дауысты → بَ تِ مُ
CVC: + сукун → بَتْ مِنْ كُتْ

Дағдыға айналғанша, сөзді бүтіндей «болжамай», оңнан солға қарай буындап оқыңыз.

«Буындар» беті — жаттығу тренажері.` },
          { id:'m3-2', title:'Соединение букв в слове', titleKk:'Сөздегі әріптердің қосылуы', body:
`Пример كِتَابٌ:
كـ + ـتـ + ـا + بٌ → كتاب

Буквы ا د ذ ر ز و «разрывают» цепочку слева от себя.

Практика: вкладка «Практика» → слова.` ,
            bodyKk:
`Мысал كِتَابٌ:
كـ + ـتـ + ـا + بٌ → كتاب

ا د ذ ر ز و әріптері өз сол жағынан тізбекті «үзеді».

Жаттығу: «Практика» беті → сөздер.` },
          { id:'m3-3', title:'Артикль ال, ة, ى, ء', titleKk:'ال, ة, ى, ء артиклі мен белгілері', body:
`ال — определённый артикль «аль».
Солнечные буквы: лям сливается (الشَّمْسُ = аш-шамсу).
Лунные: лям читается (الْقَمَرُ = аль-қамару).

ة (та марбута) — часто женский род: читается «а», при изафете — «т».
ى (алиф максура) в конце = «а».
ء хамза — гортанная смычка.` ,
            bodyKk:
`ال — анықтық артиклі «әл».
Күн әріптері: лям қосылады (الشَّمْسُ = аш-шамсу).
Ай әріптері: лям оқылады (الْقَمَرُ = әл-қамару).

ة (та марбута) — көбіне нәзік жанды жынысы: «а» болып оқылады, изафетте — «т».
ى (әліп мақсура) соңында = «а».
ء хамза — көмей тұйықталуы.` }
        ]
      },
      {
        id: 'm4', level: 4, title: 'Первые аяты', titleKk: 'Алғашқы аяттар', icon: '🕌',
        goal: 'Уверенно прочитать Аль-Фатиху и Аль-Ихляс по слогам',
        goalKk: 'Әл-Фатиха мен Әл-Ихлясты буындап сенімді оқу',
        lessons: [
          { id:'m4-1', title:'Басмала и Аль-Фатиха (1–3)', titleKk:'Басмала және Әл-Фатиха (1–3)', body:
`بِسْمِ اللّٰهِ الرَّحْمَٰنِ الرَّحِيمِ
Бисьми Лля̄хи р-Раħма̄ни р-Раħӣм

الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ
Аль-ħамду лилля̄хи рабби ль-ʿа̄ламӣн

الرَّحْمَٰنِ الرَّحِيمِ
Ар-Раħма̄ни р-Раħӣм

Читайте медленно по слогам. Затем откройте суру 1 в «Суры» и сравните.` ,
            bodyKk:
`بِسْمِ اللّٰهِ الرَّحْمَٰنِ الرَّحِيمِ
Бисьми Лля̄хи р-Раħма̄ни р-Раħӣм

الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ
Аль-ħамду лилля̄хи рабби ль-ʿа̄ламӣн

الرَّحْمَٰنِ الرَّحِيمِ
Ар-Раħма̄ни р-Раħӣм

Баяу, буындап оқыңыз. Содан кейін «Сүрелер» бөлімінен 1-сүрені ашып салыстырыңыз.` },
          { id:'m4-2', title:'Аль-Фатиха (4–7)', titleKk:'Әл-Фатиха (4–7)', body:
`مَالِكِ يَوْمِ الدِّينِ
إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ
اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ
صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ

Цель: прочитать весь текст, глядя в мусхаф, без подсказки транскрипции.` ,
            bodyKk:
`مَالِكِ يَوْمِ الدِّينِ
إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ
اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ
صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ

Мақсат: транскрипция көмегінсіз, мұсхафқа қарап, бүкіл мәтінді оқу.` },
          { id:'m4-3', title:'Аль-Ихляс (112)', titleKk:'Әл-Ихляс (112)', body:
`قُلْ هُوَ اللّٰهُ أَحَدٌ · اللّٰهُ الصَّمَدُ
لَمْ يَلِدْ وَلَمْ يُولَدْ · وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ

Короткая сура — идеальна для закрепления. Выучите наизусть после уверенного чтения.` ,
            bodyKk:
`قُلْ هُوَ اللّٰهُ أَحَدٌ · اللّٰهُ الصَّمَدُ
لَمْ يَلِدْ وَلَمْ يُولَدْ · وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ

Қысқа сүре — бекітуге өте қолайлы. Сенімді оқығаннан кейін жатқа үйреніңіз.` }
        ]
      },
      {
        id: 'm5', level: 5, title: 'Таджвид', titleKk: 'Тәжуид', icon: '🎧',
        goal: 'Базовые правила: гунна, идгам, ихфа, мадд, калькаля',
        goalKk: 'Негізгі ережелер: гунна, идгам, ихфа, мадд, калькаля',
        lessons: [
          { id:'m5-1', title:'Гунна, идгам, ихфа, изхар, иклаб', titleKk:'Гунна, идгам, ихфа, изхар, иклаб', body:
`Нун с сукуном / танвин:
• Изхар — чётко перед ء ه ع ح غ خ
• Идгам — слияние в ي ر م ل و ن
• Иклаб — перед ب ≈ «м» с гунной
• Ихфа — «скрытое н» перед остальными 15 буквами

Гунна — носовой призвук ~2 счёта (н/м с шаддой, идгам с гунной).

Подробности — вкладка «Таджвид».` ,
            bodyKk:
`Сукунды нун / тануин:
• Изхар — ء ه ع ح غ خ алдында анық
• Идгам — ي ر م ل و ن-ге қосылу
• Иклаб — ب алдында гунмен «м»-ге жақын
• Ихфа — қалған 15 әріптің алдында «жасырын н»

Гунна — ~2 есеп мұрын дыбысы (шаддалы н/м, гунмен идгам).

Толығырақ — «Тәжуид» беті.` },
          { id:'m5-2', title:'Мадд и калькаля', titleKk:'Мадд және калькаля', body:
`Мадд — удлинение. Естественный = 2 счёта. Обязательный (лазим) = 4–6.

Калькаля — «отскок» на ق ط ب ج د с сукуном (в конце слова особенно слышно).

Слушайте Мишари / Хусари на медленной скорости и повторяйте.` ,
            bodyKk:
`Мадд — созу. Табиғи = 2 есеп. Міндетті (лязим) = 4–6.

Калькаля — сукунды ق ط ب ج د-дегі «серпіліс» (сөз соңында әсіресе анық естіледі).

Мишари / Хусаридің баяу қарқынын тыңдап, қайталаңыз.` },
          { id:'m5-3', title:'Вакф (остановка)', titleKk:'Уақф (тоқтау)', body:
`م — остановиться обязательно
لا — не останавливаться
ج — можно и так и так
صلي / قلي — предпочтения при длине аята

При остановке на танвине/харакате часто читают как сукун (с нюансами таджвида).` ,
            bodyKk:
`م — міндетті түрде тоқтау
لا — тоқтамау
ج — екеуі де болады
صلي / قلي — аят ұзақтығына қарай артықшылық

Тануин/харакатта тоқтағанда көбіне сукун ретінде оқылады (тәжуид нюанстарымен).` }
        ]
      },
      {
        id: 'm6', level: 6, title: 'Свободное чтение', titleKk: 'Еркін оқу', icon: '✨',
        goal: 'Читать любой огласованный текст Корана вслух уверенно',
        goalKk: 'Харакатты кез келген Құран мәтінін дауыстап сенімді оқу',
        lessons: [
          { id:'m6-1', title:'План на 30 дней', titleKk:'30 күндік жоспар', body:
`Дни 1–7: буквы + огласовки + слоги (вкладки).
Дни 8–14: слова и фразы из «Практика».
Дни 15–21: Фатиха + Ихляс + Фаляк + Нас по мусхафу.
Дни 22–30: по ½–1 странице в день любой суры; слушайте чтеца и повторяйте.

Отмечайте уроки «Выучено» — прогресс сохранится на устройстве (в шифровании).` ,
            bodyKk:
`1–7 күндер: әріптер + харакаттар + буындар (беттер).
8–14 күндер: «Практика» бетіндегі сөздер мен тіркестер.
15–21 күндер: мұсхаф бойынша Фатиха + Ихляс + Фаляк + Нас.
22–30 күндер: күніне кез келген сүреден ½–1 бет; қариді тыңдап, қайталаңыз.

Сабақтарды «Үйренілді» деп белгілеңіз — прогресс құрылғыда (шифрланып) сақталады.` },
          { id:'m6-2', title:'Частые ошибки', titleKk:'Жиі кездесетін қателер', body:
`• Путать و с русской «в»
• Читать ع и ح как обычное «а/х»
• Глотать долгие гласные
• Игнорировать шадду
• Читать «с листа» слишком быстро — сначала точность, потом скорость

Записывайте себя на диктофон и сравнивайте с чтецом.` ,
            bodyKk:
`• و-ды орыс тіліндегі «в»-мен шатастыру
• ع мен ح-ты әдеттегі «а/х» деп оқу
• Ұзын дауыстыларды «жұтып қою»
• Шаддаға мән бермеу
• «Парақтан» тым жылдам оқу — алдымен дәлдік, сосын жылдамдық

Өзіңізді диктофонға жазып, қаримен салыстырыңыз.` },
          { id:'m6-3', title:'Что дальше', titleKk:'Одан әрі не істеу керек', body:
`1. Хифз коротких сур (30-й джуз).
2. Словарь корней (вкладка «Словарь Корана»).
3. Простой нахв: подлежащее/сказуемое.
4. Регулярное слушание одного чтеца.

Академия здесь — фундамент чтения. Глубина языка приходит годами; чтение Корана с огласовками — достижимо за недели при ежедневной практике.` ,
            bodyKk:
`1. Қысқа сүрелерді хифз ету (30-жүз).
2. Түбір сөздігі («Құран сөздігі» беті).
3. Қарапайым нахв: бастауыш/баяндауыш.
4. Бір қариді тұрақты тыңдау.

Мұндағы академия — оқудың іргетасы. Тілдің тереңдігі жылдар бойы қалыптасады; ал харакатты Құранды оқуды күнделікті жаттығумен апталар ішінде меңгеруге болады.` }
        ]
      }
    ];

