        ru:'И Зун-Нуна (Юнуса), когда он ушёл разгневанным и подумал, что Мы не справимся с ним. Затем он воззвал во мраках: «Нет божества, кроме Тебя! Пречист Ты! Воистину, я был из числа несправедливых!»',
