    const ARABIC_RULES = [
      {title:'اتجاه الكتابة · Направление', titleKk:'اتجاه الكتابة · Бағыты', ar:'من اليمين إلى اليسار',
        short:'Арабский пишется и читается справа налево.',
        shortKk:'Араб тілі оңнан солға жазылады және оқылады.',
        detail:'Арабское письмо идёт справа налево.\n\n1) Строка начинается справа; палец при чтении ведите справа налево.\n2) Мушаф (книга Корана) открывается с «другой» стороны относительно русской книги: корешок справа.\n3) Цифры в арабском тексте часто тоже идут в контексте RTL, но сами западные цифры пишутся слева направо.\n4) Практика: откройте суру «Аль-Фатиха» и проведите пальцем по строке от правого края к левому.\n5) Ошибка новичков: искать начало аята слева — начало всегда справа.',
        detailKk:'Араб жазуы оңнан солға қарай жүреді.\n\n1) Жол оң жақтан басталады; оқығанда саусақты оңнан солға қарай жүргізіңіз.\n2) Мұсхаф (Құран кітабы) орыс кітабына қарағанда «басқа» жақтан ашылады: түптеме оң жақта.\n3) Араб мәтініндегі сандар да көбіне RTL контексінде тұрады, бірақ батыс цифрлары солдан оңға жазылады.\n4) Жаттығу: «Әл-Фәтиха» сүресін ашып, саусағыңызды жол бойымен оң жиектен сол жиекке қарай жүргізіңіз.\n5) Жаңадан бастағандардың қатесі: аят басын сол жақтан іздеу — бастама әрқашан оң жақта.'},
      {title:'ربط الحروف · Соединение', titleKk:'ربط الحروف · Қосылуы', ar:'ا د ذ ر ز و لا تتصل',
        short:'Большинство букв соединяются. Не соединяются со следующей: алиф даль заль ра зай вав.',
        shortKk:'Әріптердің көбі қосылады. Келесі әріппен қосылмайтындар: әліп, дәл, заль, ра, зай, уау.',
        detail:'Соединение букв — основа арабского письма.\n\n1) Большинство букв соединяются и справа, и слева.\n2) Шесть букв НЕ соединяются со следующей: ا د ذ ر ز و (алиф, даль, заль, ра, зай, вав). После них следующая буква пишется в начальной или изолированной форме.\n3) Пример: دَرَسَ (дараса) — после даль и ра разрыв.\n4) Лам + алиф часто пишутся особым лигатурным знаком لا.\n5) Практика: сравните ببب (ббб, все соединены) и ددد (ддд, все разделены).\n6) Ошибка: пытаться «приклеить» ра или вав к следующей букве — так не пишут.',
        detailKk:'Әріптердің қосылуы — араб жазуының негізі.\n\n1) Әріптердің көбі оң жағынан да, сол жағынан да қосылады.\n2) Алты әріп келесі әріппен ҚОСЫЛМАЙДЫ: ا د ذ ر ز و (әліп, дәл, заль, ра, зай, уау). Осылардан кейін келесі әріп бастапқы немесе оқшау түрде жазылады.\n3) Мысал: دَرَسَ (дараса) — дәл мен радан кейін үзіліс бар.\n4) Лям + әліп жиі арнайы لا лигатура белгісімен жазылады.\n5) Жаттығу: ببب (ббб, барлығы қосулы) пен ددد (ддд, барлығы бөлек) салыстырыңыз.\n6) Қате: раны немесе уауды келесі әріпке «жабыстыруға» тырысу — олай жазылмайды.'},
      {title:'أشكال الحرف · Четыре формы', titleKk:'أشكال الحرف · Төрт түрі', ar:'٤ أشكال',
        short:'До 4 форм: изолированная, начальная, срединная, конечная.',
        shortKk:'Әр әріптің 4-ке дейін түрі болады: оқшау, бастапқы, ортаңғы, соңғы.',
        detail:'Одна буква — до четырёх начертаний.\n\n1) Изолированная (отдельно): как в алфавите.\n2) Начальная: в начале слова (соединяется только справа/влево по направлению письма).\n3) Срединная: в середине, соединена с обеих сторон.\n4) Конечная: в конце слова.\n5) Буквы из группы «не соединяются» имеют меньше форм.\n6) Практика: откройте вкладку «Буквы» и смотрите формы каждой буквы.\n7) Ошибка: учить только изолированную форму — в Коране почти всё в связном письме.',
        detailKk:'Бір әріптің төрт жазылу түрі болуы мүмкін.\n\n1) Оқшау (жеке): әліпбидегідей.\n2) Бастапқы: сөздің басында (жазу бағыты бойынша тек бір жағынан қосылады).\n3) Ортаңғы: сөздің ортасында, екі жағынан да қосылған.\n4) Соңғы: сөздің аяғында.\n5) «Қосылмайтын» топтағы әріптердің түрі азырақ.\n6) Жаттығу: «Әріптер» бетін ашып, әр әріптің түрлерін қараңыз.\n7) Қате: тек оқшау түрді жаттау — Құранда мәтіннің көбі байланысқан жазуда.'},
      {title:'الحركات · Огласовки', titleKk:'الحركات · Харакаттар', ar:'فتحة كسرة ضمة',
        short:'Фатха — а, касра — и, дамма — у; сукун — нет гласного; шадда — удвоение.',
        shortKk:'Фатха — «а», касра — «и», дамма — «у»; сукун — дауысты жоқ; шадда — қосарлану.',
        detail:'Огласовки (харакат) показывают краткие гласные.\n\n1) Фатха (َ) над буквой — краткий «а» (как в «ба»).\n2) Касра (ِ) под буквой — краткий «и» (как в «би»).\n3) Дамма (ُ) над буквой — краткий «у» (как в «бу»).\n4) Сукун (ْ) — гласного нет, буква «закрыта».\n5) Шадда (ّ) — удвоение согласной: сначала как с сукуном, затем с огласовкой.\n6) Без огласовок опытный читатель опирается на знание языка; в учебных мусхафах огласовки почти всегда есть.\n7) Практика: прочитайте بَ بِ بُ بْ и بَّ.',
        detailKk:'Харакаттар қысқа дауыстыларды көрсетеді.\n\n1) Фатха (َ) әріптің үстінде — қысқа «а» («ба» дегендегідей).\n2) Касра (ِ) әріптің астында — қысқа «и» («би» дегендегідей).\n3) Дамма (ُ) әріптің үстінде — қысқа «у» («бу» дегендегідей).\n4) Сукун (ْ) — дауысты жоқ, әріп «жабық».\n5) Шадда (ّ) — дауыссыздың қосарлануы: алдымен сукунмен, сосын харакатпен.\n6) Харакатсыз тәжірибелі оқырман тілді білуіне сүйенеді; оқу мусхафтарында харакаттар дерлік әрдайым бар.\n7) Жаттығу: بَ بِ بُ بْ және بَّ оқыңыз.'},
      {title:'التنوين · Танвин', titleKk:'التنوين · Тануин', ar:'فتحتان كسرتان ضمتان',
        short:'Танвин — окончание ан / ин / ун (две огласовки).',
        shortKk:'Тануин — сөз соңындағы ан / ин / ун (қос харакат).',
        detail:'Танвин — удвоение огласовки в конце слова.\n\n1) Две фатхи (ً) — «ан»; две касры (ٍ) — «ин»; две даммы (ٌ) — «ун».\n2) Обычно на неопределённых именах.\n3) При остановке (вақф) в конце аята танвин часто читается без «н»: фатхатан → долгий «а» (или с алифом), касратан/дамматан → без «н».\n4) Пример: كِتَابٌ مَّرْقُومٌ (сура 83:9) — «китабун маркум» при соединении (дамматан слышна), «китабу маркум» при остановке (дамматан пропадает).\n5) Практика: сравните чтение в середине фразы и на конце аята.\n6) Ошибка: всегда тянуть «н» на вақфе — в учебном чтении Корана вақф особый.',
        detailKk:'Тануин — сөз соңындағы харакаттың қосарлануы.\n\n1) Екі фатха (ً) — «ан»; екі касра (ٍ) — «ин»; екі дамма (ٌ) — «ун».\n2) Әдетте белгісіз есімдерде кездеседі.\n3) Аят соңында тоқтағанда (уақф) тануин көбіне «н»-сіз оқылады: фатхатан → ұзын «а» (немесе әліппен), касратан/дамматан → «н»-сіз.\n4) Мысал: كِتَابٌ مَّرْقُومٌ (83:9-сүре) — жалғасқанда «китабун маркум» (дамматан естіледі), тоқтағанда «китабу маркум» (дамматан жоғалады).\n5) Жаттығу: сөйлем ортасы мен аят соңындағы оқылуын салыстырыңыз.\n6) Қате: уақфта әрдайым «н»-ды созу — Құранды оқу үлгісінде уақф ерекше.'},
      {title:'ال · Алиф-лям', titleKk:'ال · Әліп-лям', ar:'ال التعريف',
        short:'Артикль «аль». Солнечные буквы съедают лям, лунные — нет.',
        shortKk:'«Әл» артиклі. Күн әріптері лямды «жұтады», ай әріптері — жоқ.',
        detail:'Артикль ال (аль) — определённость.\n\n1) Перед «лунными» буквами лям читается: الْكِتَاب (аль-китаб).\n2) Перед «солнечными» лям не читается, следующая буква с шаддой: الشَّمْس (аш-шамс, сура 91:1).\n3) Солнечные (примерно): ت ث د ذ ر ز س ش ص ض ط ظ ل ن.\n4) Хамзату-ль-васль у алифа артикля в начале речи произносится, в середине фразы часто «проглатывается».\n5) Практика: аль-камар (лунная, сура 91:2) vs аш-шамс (солнечная).\n6) Ошибка: читать «аль-шамс» с лям — неверно.\n7) Полный список всех 14 солнечных и 14 лунных букв, признак в мусхафе и разбор ещё двух примеров из Корана — в отдельной карточке «Солнечные и лунные буквы» на вкладке «Таджвид».',
        detailKk:'ال (әл) артиклі — анықтық білдіреді.\n\n1) «Ай» әріптерінің алдында лям оқылады: الْكِتَاب (әл-китаб).\n2) «Күн» әріптерінің алдында лям оқылмайды, келесі әріп шаддамен келеді: الشَّمْس (аш-шамс, 91:1-сүре).\n3) Күн әріптері (шамамен): ت ث د ذ ر ز س ش ص ض ط ظ ل ن.\n4) Артикльдегі әліптің хамзату-ль-уасылы сөйлем басында айтылады, сөйлем ортасында көбіне «жұтылады».\n5) Жаттығу: әл-қамар (ай, 91:2-сүре) мен аш-шамс (күн) салыстырыңыз.\n6) Қате: «әл-шамс» деп лямды оқу — дұрыс емес.\n7) Барлық 14 күн және 14 ай әрпінің толық тізімі, мусхафтағы белгісі және тағы екі Құран мысалы — «Тәжуид» қойындысындағы бөлек «Күн және ай әріптері» карточкасында.'},
      {title:'همزة · Хамза', titleKk:'همزة · Хамза', ar:'ء',
        short:'Хамза — гортанная смычка. Не путать с айн.',
        shortKk:'Хамза — көмей тұйықталуы. Айынмен шатастырмаңыз.',
        detail:'Хамза (ء) — гортанный взрыв (смычка).\n\n1) Может стоять на алиф (أ إ), на вав (ؤ), на йа (ئ) или отдельно (ء).\n2) В начале многих слов: إِنَّ الَّذِينَ (инна, сура 2:6), أَحَدٌ (ахад, сура 112:1).\n3) Не путать с ع (айн) — айн глубже и дольше «сжимает» горло.\n4) Хамзату-ль-кат‘ всегда произносится; хамзату-ль-васль — по правилам соединения.\n5) Практика: сравните أَ и عَ на слух.\n6) Ошибка: смягчать хамзу в «й» или пропускать в начале слова.',
        detailKk:'Хамза (ء) — көмейдегі тұйық жарылыс дыбысы.\n\n1) Әліпте (أ إ), уауда (ؤ), йада (ئ) немесе жеке (ء) тұруы мүмкін.\n2) Көптеген сөздердің басында: إِنَّ الَّذِينَ (инна, 2:6-сүре), أَحَدٌ (ахад, 112:1-сүре).\n3) ع (айынмен) шатастырмаңыз — айын тереңірек және көмейді ұзағырақ «қысады».\n4) Хамзату-ль-қат‘ әрқашан айтылады; хамзату-ль-уасыл — қосылу ережелері бойынша.\n5) Жаттығу: أَ мен عَ дыбысын құлақпен салыстырыңыз.\n6) Қате: хамзаны «й»-ге жұмсарту немесе сөз басында түсіріп кету.'},
      {title:'التاء المربوطة · Та марбута', titleKk:'التاء المربوطة · Та марбута', ar:'ة',
        short:'Та марбута: с огласовкой — т, при остановке — һ.',
        shortKk:'Та марбута: харакатпен — «т», тоқтағанда — «һ».',
        detail:'Та марбута (ة) — частое окончание.\n\n1) Типичный признак женского рода и многих масдаров.\n2) При чтении с огласовкой (в соединении) звучит как «т»: رَحْمَةً (рахматан).\n3) При остановке (вақф) обычно как «һ»: رَحْمَة (рахма).\n4) Не путать с обычной ت и с ھ.\n5) Практика: одно и то же слово в середине аята и на конце.\n6) Ошибка: всегда читать «т» на вақфе или всегда «һ» в соединении.',
        detailKk:'Та марбута (ة) — жиі кездесетін жалғау.\n\n1) Нәзік жанды жынысы мен көптеген масдарлардың әдеттегі белгісі.\n2) Харакатпен оқығанда (жалғасқанда) «т» болып естіледі: رَحْمَةً (рахматан).\n3) Тоқтағанда (уақф) әдетте «һ» болып естіледі: رَحْمَة (рахма).\n4) Қарапайым ت мен ھ-мен шатастырмаңыз.\n5) Жаттығу: бір сөзді аят ортасында және соңында оқыңыз.\n6) Қате: уақфта әрдайым «т» немесе жалғасқанда әрдайым «һ» деп оқу.'}
    ];

    const TAJWEED_RULES = [
      {title:'إخفاء · Ихфа', titleKk:'إخفاء · Ихфа', ar:'إخفاء النون الساكنة أو التنوين',
        short:'Нун с сукуном (или танвин) перед 15 буквами читается «скрыто», с лёгкой гунной.',
        shortKk:'Сукунды нун (немесе тануин) 15 әріптің алдында «жасырын», жеңіл гунмен оқылады.',
        detail:'Ихфа — «сокрытие».\n\n1) Когда: после нун с сукуном (نْ) или танвина идёт одна из 15 букв (не из групп изхар / идгам / иклаб).\n2) Как: язык не ставит полное касание для «н», звук уходит в нос.\n3) Гунна: около двух счётов.\n4) Пример: مِنْ شَرِّ مَا خَلَقَ (мин шарри ма халяка, сура 113:2, «Аль-Фаляк»).\n5) Ошибка: либо чёткое «н» (как изхар), либо полное слияние (как идгам) — оба неверны для ихфа.\n6) Практика: читайте медленно мин + шин, чувствуя носовой звук без удара языка.',
        detailKk:'Ихфа — «жасыру».\n\n1) Қашан: сукунды нунан (نْ) немесе тануиннен кейін 15 әріптің бірі келеді (изхар / идгам / иклаб топтарынан басқа).\n2) Қалай: тіл «н» үшін толық тимейді, дыбыс мұрынға кетеді.\n3) Гунна: шамамен екі есеп.\n4) Мысал: مِنْ شَرِّ مَا خَلَقَ (мин шарри ма халяка, 113:2-сүре, «Әл-Фаляк»).\n5) Қате: не анық «н» (изхардағыдай), не толық қосылу (идгамдағыдай) — екеуі де ихфаға дұрыс емес.\n6) Жаттығу: мин + шин деп баяу оқып, тіл соқпайынша мұрын дыбысын сезіңіз.'},
      {title:'إدغام · Идгам', titleKk:'إدغام · Идгам', ar:'إدغام النون الساكنة',
        short:'Нун с сукуном сливается со следующей буквой: йа, ра, мим, лям, вав, нун.',
        shortKk:'Сукунды нун келесі әріппен қосылады: йа, ра, мим, лям, уау, нун.',
        detail:'Идгам — слияние нун с сукуном (или танвина) со следующей буквой.\n\n1) Буквы идгама (йармлун): ي ر م ل و ن.\n2) С гунной (~2 счёта): ي و م ن (йа, вав, мим, нун).\n3) Без гунны: ل ر (лям, ра) — слияние «чистое».\n4) Отдельный звук «н» не оставляют: مِن رَّبِّهِمْ → мир-раббихим (сура 2:5).\n5) Пример с гунной: وَمِنَ النَّاسِ مَن يَقُولُ → май-якулю (сура 2:8).\n6) Ошибка: оставить слышимое «н» или дать гунну на лям/ра.\n7) Практика: медленно мин + ра, мин + йа.',
        detailKk:'Идгам — сукунды нунның (немесе тануиннің) келесі әріппен қосылуы.\n\n1) Идгам әріптері (йармлюн): ي ر م ل و ن.\n2) Гунмен (~2 есеп): ي و م ن (йа, уау, мим, нун).\n3) Гунсыз: ل ر (лям, ра) — «таза» қосылу.\n4) Бөлек «н» дыбысы қалдырылмайды: مِن رَّبِّهِمْ → мир-раббихим (2:5-сүре).\n5) Гунмен мысал: وَمِنَ النَّاسِ مَن يَقُولُ → май-якулю (2:8-сүре).\n6) Қате: естілетін «н» қалдыру немесе лям/раға гунна беру.\n7) Жаттығу: баяу мин + ра, мин + йа.'},
      {title:'إقلاب · Иклаб', titleKk:'إقلاب · Иклаб', ar:'قلب النون ميماً قبل الباء',
        short:'Перед ба нун с сукуном звучит почти как «м», с гунной.',
        shortKk:'Ба алдында сукунды нун гунмен бірге «м»-ге жақын естіледі.',
        detail:'Иклаб — «переворот» нун в мим-подобный звук.\n\n1) Только перед ب (ба).\n2) Нун с сукуном или танвин + ба → звук близкий к «м» + лёгкая гунна (~2 счёта), губы слегка смыкаются.\n3) Пример: مِن بَعْدِ مِيثَاقِهِ → мим-баъди (не «мин баъди» с чётким н; сура 2:27).\n4) В мусхафе часто ставят маленькую мим над нун как подсказку.\n5) Ошибка: читать чёткое «н» или полную мим без гунны.\n6) Практика: мин баъди, анбийа.',
        detailKk:'Иклаб — нунның мимге ұқсас дыбысқа «айналуы».\n\n1) Тек ب (ба) алдында.\n2) Сукунды нун немесе тануин + ба → «м»-ге жақын дыбыс + жеңіл гунна (~2 есеп), ерін сәл жабылады.\n3) Мысал: مِن بَعْدِ مِيثَاقِهِ → мим-баъди (анық «н»-мен «мин баъди» емес; 2:27-сүре).\n4) Мусхафта көбіне нунның үстіне кішкентай мим қойылады — белгі ретінде.\n5) Қате: анық «н» немесе гунсыз толық мим оқу.\n6) Жаттығу: мин баъди, анбийа.'},
      {title:'إظهار · Изхар', titleKk:'إظهار · Изхар', ar:'إظهار النون عند حروف الحلق',
        short:'Перед гортанными хамза ха айн ха гайн ха нун читается чётко.',
        shortKk:'Көмей әріптері хамза, ха, айын, ха, ғайын, ха алдында нун анық оқылады.',
        detail:'Изхар — ясное произношение нун.\n\n1) Когда: нун с сукуном / танвин перед гортанными: ء ه ع ح غ خ.\n2) «Н» читается чётко, без слияния и без лишней гунны.\n3) Пример: مَنْ آمَنَ بِاللَّهِ (ман амана биллях, сура 2:62), مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ (сура 106:4).\n4) Гортань работает отдельно от кончика языка.\n5) Ошибка: «проглатывать» н или тянуть гунну как в ихфа.\n6) Практика: ман амана, мин ‘ильмин — чёткое н, затем гортанная.',
        detailKk:'Изхар — нунды анық айту.\n\n1) Қашан: сукунды нун / тануин көмей әріптерінің алдында: ء ه ع ح غ خ.\n2) «Н» анық оқылады, қосылусыз және артық гунсыз.\n3) Мысал: مَنْ آمَنَ بِاللَّهِ (ман амана биллях, 2:62-сүре), مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ (106:4-сүре).\n4) Көмей тіл ұшынан бөлек жұмыс істейді.\n5) Қате: «н»-ды «жұтып қою» немесе ихфадағыдай гунна созу.\n6) Жаттығу: ман амана, мин ‘ильмин — анық «н», сосын көмей дыбысы.'},
      {title:'قلقلة · Калькаля', titleKk:'قلقلة · Калькаля', ar:'قلقلة ق ط ب ج د',
        short:'Каф та ба джим даль с сукуном — с лёгким отскоком.',
        shortKk:'Сукунды қаф, та, ба, джим, дәл — жеңіл «серпіліспен».',
        detail:'Калькаля — лёгкий «отскок» (эхо) на сукуне.\n\n1) Буквы: ق ط ب ج د (каф, та, ба, джим, даль) — запомните «кутбу джад».\n2) Когда буква с сукуном (в середине или в конце при остановке).\n3) Звук не «глухой удар», а короткая вибрация/отскок без полноценной огласовки.\n4) Сильнее на конце аята (калькаля кубра), слабее в середине (сугра).\n5) Пример: قَدْ أَفْلَحَ الْمُؤْمِنُونَ (кад афляха, сура 23:1), قُلْ هُوَ اللَّهُ أَحَدْ (при остановке, сура 112:1).\n6) Ошибка: добавлять полный гласный «а/и/у» или совсем сплющивать букву.\n7) Практика: кад, аб, медленно на конце слова.',
        detailKk:'Калькаля — сукунда болатын жеңіл «серпіліс» (жаңғырық).\n\n1) Әріптер: ق ط ب ج د (қаф, та, ба, джим, дәл) — «құтбу джад» деп жаттаңыз.\n2) Қашан: әріп сукунмен келгенде (ортасында немесе тоқтағанда соңында).\n3) Дыбыс «мылқау соққы» емес, толық харакатсыз қысқа діріл/серпіліс.\n4) Аят соңында күштірек (калькаля кубра), ортасында әлсізірек (сугра).\n5) Мысал: قَدْ أَفْلَحَ الْمُؤْمِنُونَ (қад афляха, 23:1-сүре), قُلْ هُوَ اللَّهُ أَحَدْ (тоқтағанда, 112:1-сүре).\n6) Қате: толық «а/и/у» дауыстысын қосу немесе әріпті мүлде «жаншу».\n7) Жаттығу: қад, аб — сөз соңында баяу.'},
      {title:'مد · Мадд', titleKk:'مد · Мадд', ar:'إطالة حروف المد',
        short:'Продление гласного через алиф вав йа (обычно 2 счёта).',
        shortKk:'Дауыстыны әліп, уау, йа арқылы созу (әдетте 2 есеп).',
        detail:'Мадд — продление гласного.\n\n1) Буквы мадда: ا و ي при условиях (алиф после фатхи; вав с сукуном после даммы; йа с сукуном после касры).\n2) Естественный мадд (таби‘и) — обычно 2 счёта: قَالَ (кааля, встречается по всему Корану, например 2:30).\n3) Более длинные мадды (4–6 счётов) бывают при хамзе или сукуне после мадда — это отдельные виды (муттасыль, мунфасыль, лязим, ‘арид, бадал), каждый со своим числом счётов.\n4) Не «рвать» мадд и не тянуть без правила.\n5) Пример: نُوحِيهَا — слушайте длину у чтеца.\n6) Ошибка: укорачивать алиф до краткого «а» или тянуть все гласные одинаково.\n7) Практика: сравните كَتَبَ и قَالَ.\n8) Разбор всех пяти производных видов мадда с примерами и числом счётов у каждого — в отдельной карточке «Виды мадда».',
        detailKk:'Мадд — дауыстыны созу.\n\n1) Мадд әріптері: ا و ي белгілі шарттармен (фатхадан кейін әліп; даммадан кейін сукунды уау; касрадан кейін сукунды йа).\n2) Табиғи мадд (таби‘и) — әдетте 2 есеп: قَالَ (қааля, Құранда жиі кездеседі, мысалы 2:30).\n3) Ұзынырақ мадд (4–6 есеп) хамза немесе маддтан кейінгі сукунда болады — бұл жеке түрлер (муттасиль, мунфасиль, лязим, ‘арид, бадал), әрқайсысының өз есебі бар.\n4) Маддты «үзбеңіз» және ережесіз созбаңыз.\n5) Мысал: نُوحِيهَا — қарилердің созу ұзақтығын тыңдаңыз.\n6) Қате: әліпті қысқа «а»-ға дейін қысқарту немесе барлық дауыстыны бірдей созу.\n7) Жаттығу: كَتَبَ мен قَالَ салыстырыңыз.\n8) Барлық бес туынды мадд түрінің мысалдары мен есептері — бөлек «Мадд түрлері» карточкасында.'},
      {title:'غنة · Гунна', titleKk:'غنة · Гунна', ar:'الغنة في الميم والنون',
        short:'Носовой звук на мим и нун с шаддой и в ихфа/иклаб/идгам (~2 счёта).',
        shortKk:'Шаддалы мим мен нунда, сондай-ақ ихфа/иклаб/идгамда болатын мұрын дыбысы (~2 есеп).',
        detail:'Гунна — носовой резонанс.\n\n1) Обязательна на مّ и نّ (мим/нун с шаддой) — около 2 счётов.\n2) Также в ихфа, иклаб и идгаме с гунной.\n3) Воздух идёт через нос; рот не «глотает» звук полностью.\n4) Пример: إِنَّ الَّذِينَ كَفَرُوا (инна, сура 2:6), ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ (сумма, сура 2:28).\n5) Ошибка: гунна слишком короткая (как обычная буква) или слишком длинная без счёта.\n6) Практика: инна, сумма — почувствуйте вибрацию в носу.',
        detailKk:'Гунна — мұрын резонансы.\n\n1) مّ мен نّ-де (шаддалы мим/нун) міндетті — шамамен 2 есеп.\n2) Сондай-ақ ихфа, иклаб және гунмен идгамда болады.\n3) Ауа мұрын арқылы шығады; ауыз дыбысты толық «жұтпайды».\n4) Мысал: إِنَّ الَّذِينَ كَفَرُوا (инна, 2:6-сүре), ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ (сумма, 2:28-сүре).\n5) Қате: гунна тым қысқа (әдеттегі әріптей) немесе есепсіз тым ұзын.\n6) Жаттығу: инна, сумма — мұрындағы дірілді сезіңіз.'},
      {title:'شدة · Шадда', titleKk:'شدة · Шадда', ar:'التشديد',
        short:'Шадда — буква читается удвоенно.',
        shortKk:'Шадда — әріп қосарланып оқылады.',
        detail:'Шадда (ّ) — удвоение согласной.\n\n1) Сначала буква как с сукуном, затем с своей огласовкой: ربّ = раб-б.\n2) На удвоенных ن и م обязательна гунна.\n3) Шадда не «пропуск», а полноценное удвоение.\n4) Пример: رَبِّ الْعَالَمِينَ (рабби, сура 1:2), إِنَّ الَّذِينَ كَفَرُوا (инна, сура 2:6).\n5) В идгаме следующая буква часто получает шадду — это след слияния.\n6) Ошибка: читать одну букву вместо двух или разрывать удвоение паузой.\n7) Практика: рабби, сумма — чёткое удвоение.',
        detailKk:'Шадда (ّ) — дауыссыздың қосарлануы.\n\n1) Алдымен әріп сукунмен, сосын өз харакатымен оқылады: ربّ = раб-б.\n2) Қосарланған ن мен م-де гунна міндетті.\n3) Шадда «түсіріп кету» емес, толық қосарлану.\n4) Мысал: رَبِّ الْعَالَمِينَ (раббі, 1:2-сүре), إِنَّ الَّذِينَ كَفَرُوا (инна, 2:6-сүре).\n5) Идгамда келесі әріп жиі шадда алады — бұл қосылудың ізі.\n6) Қате: екі әріптің орнына бір әріп оқу немесе қосарлануды кідіріспен үзу.\n7) Жаттығу: раббі, сумма — анық қосарлану.'},
      {title:'أحكام الميم الساكنة · Мим сакин', titleKk:'أحكام الميم الساكنة · Сукунды мим', ar:'إخفاء وإدغام وإظهار شفوي',
        short:'Мим с сукуном перед ب — ихфа шафави; перед م — идгам шафави; перед остальными — изхар шафави.',
        shortKk:'Сукунды мим ب алдында — ихфа шафауи; م алдында — идгам шафауи; қалғанында — изхар шафауи.',
        detail:'Мим сакин (مْ) — три правила, аналогичные нуну, но только для губ.\n\n1) Ихфа шафави: مْ + ب → губы смыкаются неполно, звук «м» смягчается, с гунной (~2 счёта). Пример: تَرْمِيهِم بِحِجَارَةٍ (тармихим-биҳиджара).\n2) Идгам шафави (мисляин): مْ + م → полное слияние в одну удвоенную «м» с гунной. Пример: لَهُم مَّا (ляхумма).\n3) Изхар шафави: مْ перед любой другой буквой (в т.ч. перед و и ف — здесь легко ошибиться) читается чётко, без гунны. Пример: أَنْتُمْ تَعْلَمُونَ (антум тагламун).\n4) Отличие от правил нуна: у мим сакин только 3 случая (нет иклаба), и все они связаны только с губами, а не с гортанью или языком.\n5) Ошибка: путать ихфа шафави с обычной ихфа (у нуна) или добавлять гунну при изхар шафави перед و/ف.\n6) Практика: тармихим, ляхумма, антум — медленно, чувствуя разницу в смыкании губ.',
        detailKk:'Сукунды мим (مْ) — нунға ұқсас, бірақ тек ерінге қатысты үш ереже.\n\n1) Ихфа шафауи: مْ + ب → еріндер толық жабылмайды, «м» дыбысы жұмсарады, гунмен (~2 есеп). Мысал: تَرْمِيهِم بِحِجَارَةٍ (тармихим-бихиджара).\n2) Идгам шафауи (мисляин): مْ + م → бір қосарланған «м»-ге толық қосылу, гунмен. Мысал: لَهُم مَّا (ляхумма).\n3) Изхар шафауи: مْ кез келген басқа әріптің алдында (соның ішінде و мен ف алдында да — мұнда қателесу оңай) анық, гунсыз оқылады. Мысал: أَنْتُمْ تَعْلَمُونَ (антум тағламун).\n4) Нун ережелерінен айырмашылығы: сукунды мимде тек 3 жағдай бар (иклаб жоқ), барлығы тек еріндермен байланысты, көмей немесе тілмен емес.\n5) Қате: ихфа шафауиды әдеттегі ихфамен (нунда) шатастыру немесе و/ф алдында изхар шафауида гунна беру.\n6) Жаттығу: тармихим, ляхумма, антум — баяу, еріннің жабылу айырмашылығын сезіп.'},
      {title:'إدغام المتماثلين والمتجانسين والمتقاربين · Идгам сходных букв', titleKk:'إدغام المتماثلين والمتجانسين والمتقاربين · Ұқсас әріптердің идгамы', ar:'إدغام متماثلين، متجانسين، متقاربين',
        short:'Две подряд идущие похожие буквы сливаются в одну — по трём типам сходства (не только у нуна и мима).',
        shortKk:'Қатар келген екі ұқсас әріп бір-біріне сіңіп, қосарланады — үш ұқсастық түрі бойынша (тек нун мен мимде ғана емес).',
        detail:'Помимо правил нуна и мим сакин, есть общее правило слияния похожих букв.\n\n1) Мутамасилайн (одинаковые буквы): первая с сукуном, вторая — та же буква с любой огласовкой; сливаются в одну удвоенную. Пример: اضْرِب بِّعَصَاك (идриб-би‘асак, ب+ب).\n2) Мутаджанисайн (одно место образования, разные признаки): например ت/ط/د, ث/ذ/ظ, или ل/ر. Первая с сукуном «растворяется» во второй. Пример: قَد تَّبَيَّنَ → как-таббаййана (د+ت).\n3) Мутакарибайн (близкое место образования): например ق+ك, ل+ر — частичное или полное слияние в некоторых риваятах.\n4) Общий принцип: если первая буква с сукуном совпадает или очень близка ко второй по месту выхода — язык «не отрывается» между ними, звучит как одна удвоенная буква.\n5) Ошибка: произносить обе буквы раздельно, с паузой между ними, как два разных звука.\n6) Практика: медленно повторяйте примеры, ощущая, что вторая буква «поглощает» первую.',
        detailKk:'Нун мен сукунды мим ережелерінен басқа, ұқсас әріптердің жалпы қосылу ережесі бар.\n\n1) Мутамасилайн (бірдей әріптер): бірінші әріп сукунмен, екіншісі — сол әріп кез келген харакатпен; екеуі бір қосарланған әріпке қосылады. Мысал: اضْرِب بِّعَصَاك (идриб-би‘асак, ب+ب).\n2) Мутаджанисайн (шығу орны бір, белгілері әр түрлі): мысалы ت/ط/د, ث/ذ/ظ, немесе ل/ر. Сукунды бірінші әріп екіншісіне «сіңіп кетеді». Мысал: قَد تَّبَيَّنَ → как-таббаййана (د+ت).\n3) Мутакарибайн (шығу орны жақын): мысалы ق+ك, ل+ر — кейбір риуаяттарда ішінара немесе толық қосылу болады.\n4) Жалпы қағида: сукунды бірінші әріп екіншісіне сәйкес немесе өте жақын болса, тіл екеуінің арасында «үзілмейді», бір қосарланған әріп сияқты естіледі.\n5) Қате: екі әріпті бөлек, арасында кідіріспен, екі түрлі дыбыс ретінде айту.\n6) Жаттығу: мысалдарды баяу қайталап, екінші әріптің біріншісін «жұтып алатынын» сезіңіз.'},
      {title:'أنواع المد · Виды мадда', titleKk:'أنواع المد · Мадд түрлері', ar:'مد أصلي ومد فرعي',
        short:'Мадд табии (2 счёта) — основа; мадд фарии (муттасиль, мунфасиль, лязим, ‘арид) — 4–6 счётов по причине.',
        shortKk:'Табиғи мадд (2 есеп) — негіз; фариғи мадд (муттасиль, мунфасиль, лязим, ‘арид) — себебіне қарай 4–6 есеп.',
        detail:'Мадд делится на естественный и производный — в зависимости от причины продления.\n\n1) Мадд табии (естественный) — 2 счёта, без хамзы и сукуна после буквы мадда: قَالُوا.\n2) Мадд муттасыль (соединённый) — буква мадда и хамза в одном слове: جَاءَ. Обязательно 4–5 счётов.\n3) Мадд мунфасыль (разделённый) — буква мадда в конце слова, хамза в начале следующего: بِمَا أُنزِلَ. 4–5 счётов (у некоторых чтецов допустимо 2).\n4) Мадд лязим (обязательный) — сразу после буквы мадда идёт буква с сукуном/шаддой в том же слове: الْحَاقَّةُ. Всегда 6 счётов — самый длинный вид.\n5) Мадд ‘арид ли-с-сукун (временный, из-за остановки) — краткая огласовка на предпоследней букве становится сукуном при остановке в конце аята: نَسْتَعِينُ → 2, 4 или 6 счётов на выбор чтеца.\n6) Мадд бадал — хамза стоит перед буквой мадда (а не наоборот): آمَنُوا. Обычно 2 счёта.\n7) Ошибка: давать всем маддам одинаковую длину или тянуть мадд мунфасыль там, где должен быть табии.\n8) Практика: сравните قَالَ (табии, 2), جَاءَ (муттасыль, 4–5), الْحَاقَّةُ (лязим, 6).',
        detailKk:'Мадд созылу себебіне қарай табиғи және фариғи болып бөлінеді.\n\n1) Табиғи мадд — 2 есеп, мадд әрпінен кейін хамза да, сукун да жоқ: قَالُوا.\n2) Муттасиль мадд (қосылған) — мадд әрпі мен хамза бір сөзде: جَاءَ. Міндетті түрде 4–5 есеп.\n3) Мунфасиль мадд (бөлінген) — мадд әрпі сөз соңында, хамза келесі сөздің басында: بِمَا أُنزِلَ. 4–5 есеп (кейбір қариларда 2-ге дейін рұқсат етіледі).\n4) Лязим мадд (міндетті) — мадд әрпінен кейін бірден сол сөзде сукунды/шаддалы әріп келеді: الْحَاقَّةُ. Әрқашан 6 есеп — ең ұзын түрі.\n5) ‘Арид ли-с-сукун мадд (уақытша, тоқтау салдарынан) — аят соңында тоқтағанда алдыңғы әріптегі қысқа харакат сукунға айналады: نَسْتَعِينُ → қари таңдауы бойынша 2, 4 немесе 6 есеп.\n6) Бадал мадд — хамза мадд әрпінің алдында тұрады (керісінше емес): آمَنُوا. Әдетте 2 есеп.\n7) Қате: барлық маддқа бірдей ұзындық беру немесе табиғи болуы керек жерде мунфасильді созу.\n8) Жаттығу: قَالَ (табиғи, 2), جَاءَ (муттасиль, 4–5), الْحَاقَّةُ (лязим, 6) салыстырыңыз.'},
      {title:'الوقف · Вакф (знаки остановки)', titleKk:'الوقف · Уақф (тоқтау белгілері)', ar:'علامات الوقف في المصحف',
        short:'Знаки в мусхафе подсказывают, где остановиться обязательно, где нельзя, а где на выбор чтеца.',
        shortKk:'Мусхафтағы белгілер қай жерде міндетті түрде тоқтау керек, қай жерде болмайды, қай жерде қари таңдауы бар екенін көрсетеді.',
        detail:'Вакф — временная остановка чтения с переводом дыхания.\n\n1) مـ (лязим) — обязательная остановка; продолжать без паузы — ошибка смысла.\n2) لا — остановка запрещена; если всё же остановились по нужде, лучше вернуться на пару слов назад и прочитать снова.\n3) ج (джаиз) — остановка допустима, но не обязательна — на усмотрение чтеца.\n4) صلي (аула аль-васль) — предпочтительнее продолжить чтение, чем останавливаться.\n5) قلي (аула аль-вакф) — предпочтительнее остановиться, чем продолжать.\n6) ∴ ⁘ ∴ (му‘анака) — два похожих знака над двумя близкими местами: остановиться можно только в одном из двух, не в обоих сразу.\n7) На вакфе: танвин фатхи и краткие огласовки (кроме фатхи) в конце слова снимаются и заменяются сукуном (или маддом ‘арид для долгих гласных).\n8) Ошибка: игнорировать знаки лязим/ляа, либо останавливаться ровно там, где это меняет смысл аята (например, разрывая отрицание и то, что идёт после него).\n9) Практика: откройте любую страницу в разделе «Суры» и найдите на ней разные знаки вакфа.',
        detailKk:'Уақф — оқуды тыныс алу үшін уақытша тоқтату.\n\n1) مـ (лязим) — міндетті тоқтау; кідіріссіз жалғастыру мағына қатесі болып саналады.\n2) لا — тоқтауға болмайды; қажеттіліктен тоқтап қалсаңыз, бір-екі сөз артқа қайтып, қайта оқыған жөн.\n3) ج (жаиз) — тоқтауға болады, бірақ міндетті емес — қари қалауы бойынша.\n4) صلي (аула әл-уасыл) — тоқтағаннан гөрі жалғастырған дұрысырақ.\n5) قلي (аула әл-уақф) — жалғастырғаннан гөрі тоқтаған дұрысырақ.\n6) ∴ ⁘ ∴ (му‘анақа) — жақын орналасқан екі жердің үстіндегі екі ұқсас белгі: тек екеуінің біреуінде ғана тоқтауға болады, екеуінде бірдей емес.\n7) Уақфта: сөз соңындағы тануин фатха және қысқа харакаттар (фатхадан басқа) алынып тасталып, сукунмен (немесе ұзын дауыстылар үшін ‘арид маддпен) ауыстырылады.\n8) Қате: лязим/ляа белгілерін елемеу немесе аят мағынасын өзгертетін жерде тоқтау (мысалы, болымсыздықты одан кейінгіден бөліп жіберу).\n9) Жаттығу: «Сүрелер» бөлімінен кез келген бетті ашып, сол бетте кездесетін уақф белгілерінің әр түрін тауып көріңіз.'},
      {title:'الحروف الشمسية والقمرية · Солнечные и лунные буквы', titleKk:'الحروف الشمسية والقمرية · Күн және ай әріптері', ar:'الحروف الشمسية والقمرية',
        short:'14 солнечных букв «съедают» лям артикля с удвоением следующей буквы; 14 лунных — лям произносится ясно.',
        shortKk:'14 күн әрпі артикльдің лямын қосарлана «жұтады»; 14 ай әрпінде лям анық айтылады.',
        detail:'Артикль ال перед 28 буквами ведёт себя по одному из двух сценариев.\n\n1) Лунные буквы (14): ء ب غ ح ج ك و خ ف ع ق ي م ه — лям артикля читается чётко, над ним сукун, следующая буква без шадды. Пример: الْقَمَر (аль-камар).\n2) Солнечные буквы (14): ت ث د ذ ر ز س ش ص ض ط ظ ل ن — лям не произносится, следующая буква удваивается (получает шадду). Пример: الشَّمْس (аш-шамс, а не «аль-шамс»).\n3) Признак в мусхафе: над лям солнечной буквы вообще нет огласовки, а над следующей буквой стоит шадда — это визуальная подсказка при чтении.\n4) Солнечные буквы охватывают почти все переднеязычные (зубные, альвеолярные, шипящие) звуки — их удобно выучить одним списком и повторять как считалку.\n5) Пример из Корана: فَإِنَّ مَعَ الْعُسْرِ يُسْرًا (94:5) — الْعُسر с лунной ع, лям читается; وَالتِّينِ وَالزَّيْتُونِ (95:1) — солнечные ت и ز, лям пропадает, буква удваивается.\n6) Ошибка новичков: читать «аль-» перед солнечной буквой, добавляя лишний звук «л», которого там нет.\n7) Практика: пройдитесь по алфавиту, добавляя ال к каждой букве, и слушайте — где лям слышен, а где исчезает.',
        detailKk:'ال артиклі 28 әріптің алдында екі сценарийдің біреуімен жүреді.\n\n1) Ай әріптері (14): ء ب غ ح ج ك و خ ف ع ق ي م ه — артикльдің лямы анық оқылады, үстінде сукун, келесі әріпте шадда жоқ. Мысал: الْقَمَر (әл-қамар).\n2) Күн әріптері (14): ت ث د ذ ر ز س ش ص ض ط ظ ل ن — лям айтылмайды, келесі әріп қосарланады (шадда алады). Мысал: الشَّمْس (аш-шамс, «әл-шамс» емес).\n3) Мусхафтағы белгісі: күн әрпінің алдындағы лямның үстінде мүлде харакат жоқ, ал келесі әріптің үстінде шадда тұрады — бұл оқу кезіндегі көзбен көрінетін белгі.\n4) Күн әріптері дерлік барлық тіс алды/қатты таңдай алды дыбыстарды қамтиды — оларды бір тізім ретінде жаттап, өлең сияқты қайталауға болады.\n5) Құраннан мысал: فَإِنَّ مَعَ الْعُسْرِ يُسْرًا (94:5) — الْعُسر ай әрпі ع-мен, лям оқылады; وَالتِّينِ وَالزَّيْتُونِ (95:1) — күн әріптері ت пен ز, лям жоғалады, әріп қосарланады.\n6) Жаңадан үйренушінің қатесі: күн әрпінің алдында «әл-» деп жоқ артық «л» дыбысын қосу.\n7) Жаттығу: әліпбидің бойымен жүріп, әр әріпке ال қосып, қай жерде лям естіліп, қай жерде жоғалатынын тыңдаңыз.'}
    ];

